/* Lab syllabus records: AHP-001, AHP-002, EEP-001, ECP-001, MEP-001 (source: official VMSB UTU syllabus PDF) */
const labX=(t,aim,app,f,viva)=>{const e={t,aim,app,viva};if(f)e.f=f;return e};

sylAdd("AHP-001",{
 n:"Engineering Physics Lab", s:"Phys Lab", type:"lab", ltp:"0-0-2", cr:1, sem:"I or II (group-wise)",
 marks:{sess:25,ext:25,total:50},
 obj:["To introduce the hands-on descriptions of various physical concepts of optics, mechanics, thermal physics etc. with the help of related instruments and devices."],
 out:["To formulate, analyze and solve multilevel laboratory problems in electromagnetism.","To demonstrate experimental comprehension of electric and magnetic field based systems.","To analyze the physical principle involved in various instruments.","To handle various experiments in the area of optics, mechanics and thermal physics.","To think innovatively and improve the creative skills that are essential for engineers."],
 rule:"Any twelve experiments",
 note:"Record format: aim, apparatus, circuit or ray diagram, formula with unit of every symbol, observation table with least count, calculation of one full reading, result with percentage error, precautions.\nDraw graphs on graph paper with labelled axes, units and scale, and read the slope from a large triangle, not from two data points.\nBefore each viva, memorise the formula, the meaning of every symbol, the SI unit of the answer and the two main sources of error.",
 exps:[
 labX("To determine the wavelength and fringe widths of sodium light by Young's double slit experiment","Find the fringe width and the wavelength of sodium light from the interference pattern of two coherent slits.","Sodium lamp, double slit, convex lens, micrometer eyepiece, optical bench",
  "β = λD/d, so λ = βd/D (D = slit to screen distance, d = slit separation). Sodium D-line about 589.3 nm.",
  [["Why are two separate lamps not used as the two sources?","Independent sources are not coherent; phase difference changes randomly, so no stable fringes form."],["What is the condition for a bright fringe?","Path difference equals nλ, where n is an integer (0, 1, 2 ...)."],["What happens to fringe width if the whole set-up is placed in water?","Wavelength reduces to λ/μ, so the fringe width decreases by the factor μ."]]),
 labX("To determine the wavelength of sodium light by Newton's rings","Find λ from the diameters of dark rings formed between a plano-convex lens and a glass plate.","Sodium lamp, plano-convex lens, optical flat, travelling microscope, glass plate at 45°",
  "λ = (D²ₙ₊ₚ − D²ₙ)/(4pR), D = ring diameter, R = radius of curvature of the lens.",
  [["Why is the centre of the ring system dark in reflected light?","A phase change of π occurs on reflection at the glass plate, so the reflected rays cancel at zero air thickness."],["Why do rings get closer together outward?","Diameter varies as √n, so the ring spacing shrinks as n increases."],["Why is the diameter squared plotted against ring number?","D² = 4nλR, so the plot is a straight line and the slope averages out errors."]]),
 labX("To determine the wavelength of sodium light (monochromatic source) with the help of Fresnel's biprism","Find λ by measuring fringe width, source-to-screen distance and slit separation of the virtual sources.","Fresnel biprism, sodium lamp, adjustable slit, convex lens, optical bench, micrometer eyepiece",
  "λ = βd/D, with d = √(d₁d₂) from the two lens positions giving magnified and diminished images of the slit.",
  [["How does a biprism produce coherent sources?","It divides the wavefront of a single slit into two by refraction, giving two virtual coherent images."],["Why is the slit kept parallel to the biprism edge?","The two virtual sources must be parallel line sources; otherwise the fringes are blurred or lost."],["Why is the biprism angle very small?","The prism has a very obtuse apex angle (about 179°), i.e. base angles of only about 0.5°, so the deviation is small, the virtual sources are close together and the fringes are wide enough to see."]]),
 labX("To determine the wavelength of He-Ne laser using Michelson-Morley interferometer","Find λ by counting fringes that shift as one mirror of the interferometer is moved a known distance.","He-Ne laser, Michelson interferometer, beam splitter, compensating plate, micrometer screw, screen",
  "λ = 2d/N, d = mirror displacement, N = number of fringes crossing the reference point. He-Ne is 632.8 nm.",
  [["Why is the mirror displacement d related to 2d/λ fringes?","The beam travels the extra path twice, so path change is 2d; each λ of path change shifts one fringe."],["What is the purpose of the compensating plate?","It makes the glass path equal in both arms, which is needed for white-light fringes and keeps the path difference the same for all wavelengths."],["What kind of fringes appear with a laser and parallel mirrors?","Circular fringes of equal inclination are seen when the mirrors are nearly perpendicular."]]),
 labX("To determine the separation between the plates of a Fabry-Perot etalon and the order of interference at the centre of Fabry-Perot fringes","Find the etalon spacing d and central-fringe order from the measured ring diameters.","Fabry-Perot etalon, sodium or mercury source, convex lens, telescope or travelling microscope, screen",
  "2d cosθ = nλ; central order n = 2d/λ. For a close doublet, d = λ₁λ₂/[2(λ₁ − λ₂)].",
  [["How does a Fabry-Perot etalon differ from a Michelson interferometer?","It uses multiple-beam interference, giving much sharper fringes than the two-beam Michelson."],["What is the free spectral range?","Δλ = λ²/2d, the largest wavelength range without order overlap."],["Why are the rings sharp and narrow?","Many partially reflected beams add up; only near-exact phase matching gives a bright maximum."]]),
 labX("To determine the specific rotation of cane sugar solution with the help of polarimeter","Measure the optical rotation of sugar solutions of known concentration and find the specific rotation.","Laurent half-shade polarimeter, sodium lamp, polarimeter tube, cane sugar solutions, balance",
  "[α] = θ/(l·c), θ = rotation (degrees), l = tube length (dm), c = concentration (g/cm³).",
  [["What is specific rotation?","Rotation produced by a 1 dm tube containing 1 g/cm³ of the optically active solution at a given wavelength and temperature."],["Why is a half-shade device used?","Matching two half-fields to equal brightness is far more sensitive than judging the darkest position."],["Is cane sugar dextro- or laevorotatory?","Dextrorotatory; it rotates the plane of polarisation clockwise."]]),
 labX("To determine the wavelength of prominent spectral lines of mercury light by plane diffraction grating","Find λ of the violet, green and yellow mercury lines using a spectrometer and a grating.","Spectrometer, plane diffraction grating, mercury vapour lamp, spirit level, reading lens",
  "nλ = (a + b) sinθ, and (a + b) = 1/N (grating element = 1/lines per unit length).",
  [["What is the grating element?","The distance (a + b) between the centres of two adjacent slits, equal to 1/N."],["Why is normal incidence adjusted before measurement?","The formula nλ = (a + b) sinθ holds only when light falls normal to the grating."],["What limits the maximum order observable?","sinθ cannot exceed 1, so n ≤ (a + b)/λ."]]),
 labX("To determine the numerical aperture of an optical fiber","Measure the acceptance cone of a fibre and calculate its numerical aperture.","Optical fibre with light source, NA measurement jig with screen, metre scale, power supply",
  "NA = sinθ₀ = r/√(r² + L²) = √(n₁² − n₂²), r = spot radius, L = fibre-screen distance.",
  [["What is the numerical aperture?","The sine of the maximum acceptance angle; it measures the light-gathering ability of the fibre."],["Why must the core index exceed the cladding index?","Total internal reflection at the core-cladding boundary needs light moving from denser to rarer medium."],["What is the acceptance angle?","The maximum angle to the axis at which incident light is still guided by total internal reflection."]]),
 labX("To determine the wavelength of given laser by plane diffraction grating","Find the laser wavelength from the diffraction orders on a screen.","Laser source, plane diffraction grating, screen, metre scale, stand",
  "nλ = d sinθ, sinθ = x/√(x² + L²), d = 1/N (x = order position, L = grating-screen distance).",
  [["Why are laser spots sharp and well separated?","The laser is highly monochromatic and collimated, so each order forms a narrow spot at a fixed angle."],["How would you get more orders on the screen?","Use a grating with a larger line spacing (fewer lines per mm), or a shorter laser wavelength."],["What safety precaution is essential?","Never look into the beam or its reflection; avoid mirror-like objects in its path."]]),
 labX("To determine the resolving power of a telescope","Find the resolving power of a telescope for different aperture widths using a distant pair of objects.","Telescope with adjustable slit, two distant thin vertical lines, metre scale, travelling microscope",
  "Minimum resolvable angle dθ = 1.22λ/a for a circular aperture and dθ = λ/a for the rectangular slit used in this experiment; R.P. = 1/dθ (a = aperture width). Experimentally dθ = s/L.",
  [["State the Rayleigh criterion.","Two point sources are just resolved when the central maximum of one falls on the first minimum of the other."],["How can the resolving power be increased?","Increase the objective aperture or use a shorter wavelength."],["Why do astronomers build large-diameter telescopes?","Both light gathering and resolving power increase with the aperture."]]),
 labX("To determine the resistance per unit length of Carey Foster's bridge wire and to determine the specific resistance of a given wire","Find the resistance per unit length of the bridge wire, then use it to find an unknown resistance and the specific resistance of a wire.","Carey Foster bridge, standard resistances, resistance box, galvanometer, battery, jockey, unknown wire, screw gauge",
  "X − Y = ρ(l₂ − l₁) (ρ = resistance per unit length, l₁, l₂ = balance lengths before and after interchange); specific resistance = Xπr²/L.",
  [["Why are the end resistances not needed?","Interchanging the resistances cancels the unknown end resistances, which is the key property of the Carey Foster method."],["Why should the ratio arms P and Q be nearly equal?","Balance then falls near the middle of the wire, where sensitivity and uniformity are best."],["Why is the jockey not slid along the wire?","Sliding damages the wire and changes its uniform cross-section."]]),
 labX("To determine the variation of magnetic field along the axis of a current carrying coil and then to estimate the radius of the coil","Plot the axial field of a circular coil against distance and use the points of inflexion to estimate the coil radius.","Stewart and Gee apparatus (tangent galvanometer type), rheostat, ammeter, battery, commutator, compass needle",
  "B = μ₀nIa²/[2(a² + x²)^{3/2}]. The graph has inflexion points at x = ±a/2, separated by a.",
  [["State the Biot-Savart law.","dB = (μ₀/4π) I dl sinθ / r²; field due to a current element varies inversely as the square of distance."],["What is the field at the centre of a circular coil?","B = μ₀nI/2a, where n is the number of turns and a is the radius."],["Why is the reading reversed by the commutator?","Reversing the current and averaging the readings removes errors from imperfect alignment of the coil and needle, zero error and pivot friction."]]),
 labX("To draw the hysteresis curve and hysteresis loss of a given ferromagnetic sample and from this to determine magnetic susceptibility and permeability: (i) obtain the B-H curve on a C.R.O. using a solenoid and determine the related magnetic constants; (ii) determine hysteresis loss using C.R.O.","Display the B-H loop on a CRO, find retentivity, coercivity, permeability, susceptibility and the loss per cycle.","CRO, solenoid with specimen, integrating circuit (R, C), resistances, AC supply, transformer",
  "Energy loss per unit volume per cycle = area of the B-H loop; μ = B/H and χ = μ/μ₀ − 1 = μᵣ − 1.",
  [["Why does the area of the loop represent energy loss?","Work done per unit volume per cycle is the integral of H dB, which equals the enclosed loop area."],["Which loop suits a transformer core, and why?","A narrow loop of soft iron, since it has low coercivity and low hysteresis loss."],["Define retentivity and coercivity.","Retentivity is the flux density left when H = 0; coercivity is the reverse field needed to bring B to zero."]]),
 labX("To calibrate a given voltmeter and ammeter by means of a potentiometer","Check the readings of a voltmeter and ammeter against the potentiometer and draw calibration curves.","Potentiometer, accumulator, standard cell, voltmeter, ammeter, rheostat, standard resistance, galvanometer, key",
  "E₁/E₂ = l₁/l₂; potential gradient k = V/L; true p.d. = k·l; true current I = V/R across a standard resistor.",
  [["Why is a potentiometer preferred to a voltmeter for measuring e.m.f.?","At balance it draws no current from the cell, so it measures the true e.m.f., not the terminal voltage."],["What is the potential gradient?","The fall in potential per unit length of the potentiometer wire."],["What does a calibration curve show?","The error (true − observed) against the reading, used to correct the instrument."]]),
 labX("To study the Hall effect and determine Hall coefficient, carrier density and mobility of a given semiconductor material using Hall effect set up","Measure the Hall voltage, find the Hall coefficient, sign and density of charge carriers and the mobility.","Hall effect apparatus, semiconductor Hall probe, electromagnet with power supply, gaussmeter, constant-current source, digital millivoltmeter",
  "R_H = V_H t/(I B) = 1/(ne); n = 1/(e R_H); mobility μ = |R_H|σ.",
  [["What is the Hall effect?","A transverse voltage appears across a current-carrying conductor placed in a magnetic field perpendicular to the current."],["What can be found from the sign of the Hall voltage?","The type of majority carriers: negative R_H for electrons (n-type), positive for holes (p-type)."],["Why is the Hall voltage larger in semiconductors than in metals?","V_H is proportional to 1/n, and carrier density in semiconductors is much smaller."]]),
 labX("To determine the resistivity and energy band gap of a semiconductor (germanium) using the four probe method; (ii) to determine the band gap in a semiconductor using a PN junction diode","Find resistivity and band gap from the temperature dependence of resistance of a Ge crystal, and cross-check with a PN diode.","Four probe apparatus, Ge crystal, oven with thermometer, constant-current source, millivoltmeter, PN junction diode",
  "ρ = ρ₀/G(w/s), ρ₀ = (V/I)·2πs; Eg = 2k × slope of ln ρ against 1/T. For the diode, the slope of ln I₀ against 1/T gives Eg = k × slope.",
  [["Why are four probes used instead of two?","The current probes carry the current while the voltage probes draw none, so contact resistance is removed."],["What is the band gap of Ge?","About 0.67 eV at room temperature."],["How does the resistance of an intrinsic semiconductor change with temperature?","It falls exponentially because more carriers are excited across the band gap."]]),
 labX("To determine the V-I characteristics of a diode and determine the energy gap of the semiconductor","Plot forward and reverse V-I curves, find the knee voltage and dynamic resistance, and deduce the band gap.","PN junction diode, DC supply, rheostat, voltmeter, milliammeter, microammeter, heating arrangement, thermometer",
  "I = I₀[exp(eV/ηkT) − 1]; dynamic resistance r = ΔV/ΔI; band gap from the temperature variation of reverse saturation current I₀ ∝ exp(−Eg/kT).",
  [["What are the knee voltages of Ge and Si diodes?","About 0.3 V for germanium and 0.7 V for silicon."],["How does temperature affect the reverse saturation current?","It roughly doubles for every 10 °C rise because minority carriers increase."],["Why is a series resistance used in forward bias?","To limit the current below the rated value and avoid burning the diode."]]),
 labX("To study V-I characteristics of LED and laser sources and hence to determine the responsivity of a photo receiver","Plot V-I curves of an LED and a laser diode, and find the receiver's response to optical power.","LED, laser diode, photodiode or photo receiver, DC supply, voltmeter, microammeter, optical power meter",
  "Responsivity R = I_ph/P (A/W); threshold voltage found from the forward-characteristic knee.",
  [["How does an LED emit light?","Electrons recombine with holes in the forward-biased junction and release photons (spontaneous emission)."],["What is responsivity of a photodetector?","The photocurrent produced per unit incident optical power, in A/W."],["How does laser emission differ from LED emission?","A laser uses stimulated emission and gives coherent, narrow, directional light."]]),
 labX("To measure the optical loss, fibre length and hence determine the attenuation coefficient of an optical fibre at different wavelengths and to find the radius of curvature of the optical fibre","Measure power loss over fibre length to find the attenuation coefficient, and examine loss due to bending.","Optical fibre spools of known length, LED sources of different wavelengths, optical power meter, mandrels of known radius",
  "α (dB/km) = (10/L) log₁₀(P_in/P_out); bending increases the loss as the radius of curvature falls.",
  [["What is attenuation in a fibre?","Loss of optical power with distance, measured in dB/km."],["Name two causes of fibre loss.","Absorption and Rayleigh scattering (also bending and connector losses)."],["Which wavelengths are used in fibre communication?","The low-loss windows near 850 nm, 1310 nm and 1550 nm."]]),
 labX("Comparison of P-I characteristics of LED and ILD and hence determine the region of operations and laser threshold current","Plot optical power against drive current for an LED and an injection laser diode, and find the threshold current.","LED, injection laser diode (ILD), power supply, ammeter, optical power meter, driver circuit",
  "Below threshold the ILD acts like an LED; above the threshold current I_th the output rises steeply. Slope efficiency = ΔP/ΔI.",
  [["What is the threshold current of a laser diode?","The current above which stimulated emission dominates and the output rises sharply."],["Why is the LED P-I curve nearly linear?","Its output is spontaneous emission, proportional to injected current, with no threshold."],["Which source is better for a long-distance fibre link?","ILD, because of its narrow spectrum and high power."]]),
 labX("To find out the fill factor of a given solar cell","Plot the I-V curve of a solar cell under illumination and find the fill factor and efficiency.","Solar cell, light source, rheostat, voltmeter, ammeter, lux meter or intensity meter",
  "FF = (V_m I_m)/(V_oc I_sc); efficiency η = V_m I_m/P_in.",
  [["Define fill factor.","Ratio of the maximum power output to the product of open-circuit voltage and short-circuit current."],["What is the working principle of a solar cell?","The photovoltaic effect: photons create electron-hole pairs, which the junction field separates."],["What is a typical fill factor for silicon cells?","About 0.7 to 0.8."]]),
 labX("To verify Stefan's law by electrical method","Show that power radiated by a hot filament varies as the fourth power of its absolute temperature.","Bulb filament, variable DC supply, voltmeter, ammeter, connecting wires",
  "P = σA(T⁴ − T₀⁴) ∝ T⁴; a log-log plot of P against T has slope 4. T is found from R = R₀[1 + α(T − T₀)].",
  [["State Stefan's law.","Energy radiated per unit area per second by a black body is proportional to T⁴."],["What is the value of the Stefan-Boltzmann constant?","σ = 5.67 × 10⁻⁸ W m⁻² K⁻⁴."],["Why is the filament temperature found from its resistance?","Resistance of a metal varies with temperature in a known way, so R gives T without a pyrometer."]]),
 labX("To determine the numerical aperture and to evaluate V-number of a given optical fibre","Find the NA of a fibre, then compute the V-number and the number of guided modes.","Optical fibre, He-Ne or LED source, NA jig, screen, scale, core radius data",
  "V = (2πa/λ)·NA; single mode if V < 2.405; number of modes ≈ V²/2 for a step-index fibre.",
  [["What does the V-number represent?","A normalised frequency that decides how many modes the fibre supports."],["What is the condition for single-mode operation?","V must be less than 2.405."],["How can a multimode fibre be made single-mode?","Reduce the core radius or the NA, or use a longer wavelength."]]),
 labX("To determine the susceptibility of paramagnetic solution (Quincke's tube method)","Find the volume susceptibility of a paramagnetic solution from the rise of its column between magnet poles.","Quincke's tube, electromagnet, paramagnetic solution (FeCl₃ or MnSO₄), travelling microscope, gaussmeter, power supply",
  "χ = 2ρgh/(μ₀H²) = 2μ₀ρgh/B² (air susceptibility neglected), h = rise of the meniscus.",
  [["Why does the liquid level rise in the field?","A paramagnetic liquid is pulled into the region of strong field, so the meniscus rises."],["Distinguish diamagnetic and paramagnetic materials.","Diamagnetic materials have small negative χ; paramagnetic materials have small positive χ."],["How does paramagnetic susceptibility depend on temperature?","By Curie's law, χ ∝ 1/T."]]),
 labX("To determine the frequency of A.C. mains with a sonometer using non-magnetic and magnetic wire","Find the mains frequency by adjusting the vibrating length of a wire until it resonates with the AC-driven force (non-magnetic wire carrying the AC in a permanent magnet's field; magnetic wire in the field of an AC electromagnet).","Sonometer, non-magnetic wire (brass), magnetic wire (iron or steel), step-down transformer, permanent horseshoe magnet, electromagnet on AC mains, weights, paper rider",
  "Non-magnetic wire (carries the AC through a step-down transformer, placed in a permanent magnet's field): the force reverses every half cycle, so it vibrates at f and f = (1/2l)√(T/m). Magnetic wire (lies in the field of an AC electromagnet): it is attracted in both half cycles, so it vibrates at 2f and f = (1/4l)√(T/m); m = mass per unit length, T = tension.",
  [["Why does a magnetic wire vibrate at twice the mains frequency?","The magnet attracts the wire in both half cycles, so the force repeats twice per cycle."],["How do you know resonance has been reached?","The paper rider is thrown off or vibrates with maximum amplitude."],["What is the mains frequency in India?","50 Hz."]]),
 labX("To determine the frequency of an electrically maintained tuning fork by Melde's experiment: transverse and longitudinal modes","Find the tuning-fork frequency from the loop length of a vibrating string in both arrangements.","Electrically maintained tuning fork, string, pan with weights, pulley, metre scale, balance",
  "Transverse mode (prong vibrates perpendicular to the string): n = (p/2l)√(T/m). Longitudinal mode (prong vibrates along the string): n = (p/l)√(T/m); p = number of loops in length l, T = tension, m = mass per unit length.",
  [["Why is the string frequency half the fork frequency in the longitudinal mode?","The prong changes the string tension once per prong vibration, but tension peaks twice per string vibration (at each extreme displacement), so the string makes one vibration for every two of the prong and the fork frequency is twice the string frequency."],["How does the loop length depend on tension?","λ ∝ √T, so loops get longer as the tension rises."],["Why are stationary waves formed on the string?","The incident and reflected transverse waves superpose to form nodes and antinodes."]])
 ]
});

sylAdd("AHP-002",{
 n:"Engineering Chemistry Lab", s:"Chem Lab", type:"lab", ltp:"0-0-2", cr:1, sem:"I or II (group-wise)",
 marks:{sess:25,ext:25,total:50},
 obj:["To provide students with practical knowledge of quantitative analysis of materials and instrumental methods, developing experimental skills and technical competence."],
 out:["To give knowledge of different analytical techniques of chemistry.","To give an idea about volumetric and gravimetric methods of analysis.","To give knowledge about several volumetric methods used in industries like water, hospitals, dyeing, metallurgy etc.","To give an idea about some old and latest instrumental methods of analysis like viscometric, surface tension and conductivity methods.","To give an idea about some useful industrial techniques like chromatography, bomb calorimeter and coal analysis etc."],
 rule:"Any ten experiments",
 ref:["Vogel's Textbook of Quantitative Chemical Analysis, ELBS Longman","R.N. Goyal and H. Goel, Engineering Chemistry, An e-publication"],
 note:"Record format: aim, chemicals and apparatus, principle with balanced equation, indicator and end point colour, burette table with three concordant readings (difference 0.1 mL), calculation with N₁V₁ = N₂V₂, result and precautions.\nRinse the burette with the titrant and the pipette with the solution before use; read the lower meniscus at eye level, and write burette readings to 0.05 mL.\nBe ready to state the colour change, the pH range of the indicator and why each reagent is used; examiners ask these first.",
 exps:[
 labX("Determination of viscosity by Ostwald viscometer and the molecular weight of a polymer by viscosity measurement","Find the relative viscosity of a liquid and use the intrinsic viscosity of polymer solutions to estimate molecular weight.","Ostwald viscometer, stop-watch, thermostat bath, specific gravity bottle, polymer solutions of different concentrations",
  "η₁/η₂ = (ρ₁t₁)/(ρ₂t₂); Mark-Houwink equation [η] = K·Mᵃ.",
  [["Why must the viscometer be kept vertical?","Flow time depends on the hydrostatic head, which changes if the tube is tilted."],["What is the SI unit of viscosity?","Pa·s (N s m⁻²); in CGS it is poise."],["How does temperature affect the viscosity of a liquid?","Viscosity decreases as temperature rises, so a thermostat is required."]]),
 labX("Determination of surface tension of a liquid by stalagmometer","Find the surface tension of a liquid by comparing drop numbers with water (drop-number method).","Stalagmometer, specific gravity bottle, water, test liquid, rubber tube, clamp stand",
  "γ₁/γ₂ = (n₂ρ₁)/(n₁ρ₂) where n = number of drops for the same volume and ρ = density.",
  [["Why do drops form?","Surface tension holds the drop until its weight equals the surface-tension force at the tip."],["How does temperature affect surface tension?","It decreases as temperature rises."],["Why are drops counted for the same fixed volume?","Both liquids must be compared for equal volume so that drop number depends only on γ and ρ."]]),
 labX("Determination of chloride content of water by Mohr's method","Estimate chloride in a water sample by titration with standard AgNO₃ using K₂CrO₄ indicator.","Burette, pipette, conical flask, standard AgNO₃ solution, 5 % K₂CrO₄ indicator, water sample",
  "Cl⁻ + Ag⁺ → AgCl (white); end point: red-brown Ag₂CrO₄. Chloride (mg/L) = (V × N × 35.5 × 1000)/V_sample.",
  [["What is the indicator and the end-point colour?","Potassium chromate; the first permanent red-brown Ag₂CrO₄ appears."],["Why must the pH lie between 6.5 and 10?","In acid the chromate is converted to dichromate; in strong alkali Ag₂O precipitates."],["Why does AgCl precipitate before Ag₂CrO₄?","AgCl is less soluble, so it precipitates first, and Ag₂CrO₄ forms only when chloride is exhausted."]]),
 labX("Determination of cell constant and conductance of a solution using conductivity meter","Calibrate a conductivity cell with KCl and measure the conductance of a given solution.","Conductivity meter, conductivity cell, 0.01 M KCl, given solutions, thermostat, volumetric flasks",
  "Cell constant = l/A = κ/G; κ of 0.01 M KCl is 1.413 mS/cm at 25 °C. Λ = 1000κ/C (κ in S/cm, C in mol/L).",
  [["What is the cell constant?","The ratio of electrode separation to electrode area (l/A), in cm⁻¹."],["Why is alternating current used?","It prevents electrolysis and polarisation at the electrodes."],["How does the conductivity of an electrolyte change with temperature?","It increases, roughly 2 % per °C, as ionic mobility rises."]]),
 labX("Determination of saponification/acid value of oil","Find the acid value or saponification value of an oil sample by titration.","Oil sample, alcoholic KOH, standard HCl or oxalic acid, phenolphthalein, reflux condenser, burette",
  "Acid value = 56.1 × N × V/W (mg KOH per g). Saponification value = 56.1 × N × (B − S)/W; B = blank, S = sample titre.",
  [["Define saponification value.","Milligrams of KOH needed to saponify 1 g of oil or fat."],["What does a high acid value indicate?","The oil has turned rancid because free fatty acids have formed."],["Why is a blank titration run?","It gives the KOH used up without oil, so the difference measures KOH consumed by the oil."]]),
 labX("Synthesis of aspirin drug in the lab","Prepare aspirin (acetylsalicylic acid) from salicylic acid and acetic anhydride, purify it and calculate the yield.","Salicylic acid, acetic anhydride, conc. H₂SO₄ or H₃PO₄, conical flask, water bath, Buchner funnel, ethanol, ice",
  "C₇H₆O₃ + (CH₃CO)₂O → C₉H₈O₄ + CH₃COOH; M(aspirin) = 180 g/mol; m.p. about 135 °C; % yield = (actual/theoretical) × 100.",
  [["What is the role of the acid catalyst?","It activates the acetic anhydride so that the phenolic -OH of salicylic acid is acetylated faster."],["How is the purity of aspirin tested?","Ferric chloride gives a purple colour if unreacted salicylic acid (a phenol) remains."],["Why is the product recrystallised?","To remove impurities and unreacted salicylic acid, giving pure aspirin crystals."]]),
 labX("Chemical analysis of a given salt","Identify the anion and cation present in a given simple salt through systematic tests.","Salt sample, test tubes, dil. HCl, dil. and conc. H₂SO₄, BaCl₂, AgNO₃, NaOH, NH₄OH, H₂S or thioacetamide, Bunsen burner",
  "Cation groups: I (dil. HCl, Pb²⁺), II (H₂S in acid, Cu²⁺), III (NH₄Cl + NH₄OH, Fe³⁺, Al³⁺), IV (H₂S in alkali, Zn²⁺, Mn²⁺), V ((NH₄)₂CO₃, Ca²⁺, Ba²⁺).",
  [["Why is NH₄Cl added before NH₄OH for Group III?","It suppresses OH⁻ by the common ion effect so that only Group III hydroxides precipitate."],["What is the group reagent for Group I cations?","Dilute hydrochloric acid, which precipitates the chlorides of Pb²⁺, Ag⁺ and Hg₂²⁺."],["How is carbonate confirmed?","Dilute acid gives effervescence of CO₂, which turns lime water milky."]]),
 labX("Determination of the partition coefficient of a solute in two immiscible liquids","Find the distribution coefficient of a solute (e.g. acetic acid or iodine) between two immiscible solvents.","Separating funnels, water and organic solvent (benzene or butanol), acetic acid, NaOH, phenolphthalein, burette",
  "K_D = C₁/C₂ (Nernst distribution law), at constant temperature and the same molecular form in both solvents.",
  [["State the Nernst distribution law.","At constant temperature, a solute distributes between two immiscible solvents in a constant concentration ratio."],["When does the law fail?","When the solute associates or dissociates in one solvent, or the solvents are not immiscible."],["What is the use of the law in industry?","Solvent extraction: repeated small extractions remove more solute than one large extraction."]]),
 labX("Determination of adsorption of acetic acid by charcoal","Verify the Freundlich adsorption isotherm for acetic acid on charcoal.","Activated charcoal, acetic acid of varied concentrations, conical flasks, shaker, burette, NaOH, phenolphthalein",
  "x/m = kC^{1/n}, i.e. log(x/m) = log k + (1/n) log C; the plot is a straight line.",
  [["What is adsorption?","The accumulation of a substance on the surface of a solid or liquid, unlike absorption which is bulk uptake."],["What does the slope of the log-log plot give?","1/n, the adsorption intensity, a value between 0 and 1."],["How does temperature affect physical adsorption?","It decreases with a temperature rise, since adsorption is exothermic."]]),
 labX("Removal of hardness of water by ion exchange column","Demonstrate softening of hard water by passing it through a cation exchange resin and measure hardness before and after.","Ion exchange column with cation resin, hard water, EDTA, Eriochrome Black-T, NH₄Cl-NH₄OH buffer, burette",
  "2R-H + Ca²⁺ → R₂Ca + 2H⁺; regeneration with dilute HCl or H₂SO₄. Hardness (ppm CaCO₃) = (V × M × 100 × 1000)/V_sample.",
  [["How does an ion exchanger remove hardness?","The resin exchanges Ca²⁺ and Mg²⁺ ions in the water for H⁺ or Na⁺ ions."],["How is an exhausted cation resin regenerated?","By washing with dilute HCl or H₂SO₄ so that H⁺ replaces the retained Ca²⁺ and Mg²⁺."],["Why is a cation exchanger followed by an anion exchanger for demineralisation?","The cation resin removes metal ions and the anion resin removes anions, giving demineralised water."]]),
 labX("Determination of Rf value using paper/thin layer chromatography","Separate the components of a mixture and calculate the Rf value of each.","Chromatography paper or TLC plate, developing chamber, solvent, capillary, mixture of amino acids or dyes, ruler",
  "Rf = distance moved by solute / distance moved by solvent front (always less than 1).",
  [["Why is Rf always less than 1?","The solute cannot travel farther than the solvent front."],["What factors affect Rf?","The solvent system, stationary phase, temperature and the nature of the compound."],["How are colourless spots located?","With a spray such as ninhydrin, by iodine vapour, or under UV light."]]),
 labX("Determination of temporary and permanent hardness of water by complexometric titration","Find total and permanent hardness of water using EDTA and hence calculate temporary hardness.","Standard EDTA solution, Eriochrome Black-T, NH₄Cl-NH₄OH buffer (pH 10), burette, pipette, hard water, boiled water",
  "Total hardness (ppm CaCO₃) = (V × M_EDTA × 100 × 1000)/V_sample; temporary = total − permanent.",
  [["Why is a buffer of pH 10 used?","EDTA complexes with Ca²⁺ and Mg²⁺ properly and the indicator changes colour sharply at this pH."],["What is the end-point colour change?","Wine red to clear blue."],["What causes temporary hardness?","Dissolved bicarbonates of calcium and magnesium; boiling removes them."]]),
 labX("Determination of rate constant of a reaction","Find the first-order rate constant of acid hydrolysis of methyl acetate by titration at different times.","Methyl acetate, 0.5 N HCl, standard NaOH, phenolphthalein, ice-cold water, stop-watch, thermostat",
  "k = (2.303/t) log[(V∞ − V₀)/(V∞ − V_t)]; half-life t½ = 0.693/k.",
  [["What is the order of the reaction studied?","Pseudo first order, since water is in large excess."],["What is the role of HCl?","It acts as a catalyst, while its concentration stays constant."],["Why are the samples run into ice-cold water?","This quenches the reaction so that the titre is taken at the required time."]]),
 labX("To determine the ferrous content in the supplied sample of iron ore by titrimetric analysis against standard K₂Cr₂O₇ solution using K₃Fe(CN)₆ as external indicator","Estimate ferrous iron in an ore solution by titration with standard dichromate, using a spot test for the end point.","Iron ore solution, standard K₂Cr₂O₇, K₃Fe(CN)₆ external indicator, white tile, burette, pipette, dil. H₂SO₄",
  "Cr₂O₇²⁻ + 6Fe²⁺ + 14H⁺ → 2Cr³⁺ + 6Fe³⁺ + 7H₂O; equivalent weight of Fe = 56.",
  [["Why is an external indicator used?","Ferricyanide reacts with Fe²⁺ and would consume it if added to the flask, so drops are tested on a tile."],["What is the end-point indication?","A drop of the titration mixture no longer gives a blue colour with the indicator."],["What is the oxidation state change of chromium?","Cr goes from +6 in dichromate to +3."]]),
 labX("To determine the constituents and amount of alkalinity of the supplied water sample","Find the hydroxide, carbonate and bicarbonate alkalinity of water using phenolphthalein and methyl orange end points.","Water sample, standard H₂SO₄ or HCl, phenolphthalein, methyl orange, burette, pipette, conical flask",
  "P = phenolphthalein titre, M = methyl orange titre. P = 0: HCO₃⁻ only; P = M: OH⁻ only; P = ½M: CO₃²⁻ only; P < ½M: CO₃²⁻ + HCO₃⁻; P > ½M: OH⁻ + CO₃²⁻.",
  [["Why can OH⁻ and HCO₃⁻ not coexist?","They react to give carbonate: OH⁻ + HCO₃⁻ → CO₃²⁻ + H₂O."],["What do the phenolphthalein and methyl orange end points mark?","Phenolphthalein marks about pH 8.3 (OH⁻ and half of CO₃²⁻); methyl orange marks about pH 4.5 (all alkalinity)."],["Why is alkalinity in water important?","It indicates buffering and scale or corrosion tendency in boilers and pipes."]])
 ]
});

sylAdd("EEP-001",{
 n:"Basic Electrical Engineering Lab", s:"BEE Lab", type:"lab", ltp:"0-0-2", cr:1, sem:"I or II (group-wise)",
 marks:{sess:25,ext:25,total:50},
 obj:["To introduce hands-on descriptions of various concepts of electrical systems and different laws and theorems, and to understand the mechanism of DC generator, DC shunt motor and three phase induction motor."],
 out:["Understand the characteristics of maximum power transfer and superposition theorems.","Analyze the efficiency of a single phase transformer by load test.","Analyze the load characteristics of a DC generator and the control of a DC shunt motor.","Understand KCL, KVL and Thevenin's and Norton's theorems.","Improve skills of team work, technical communication and report writing."],
 rule:"A minimum of 08 experiments from the following",
 note:"Record format: aim, apparatus with ratings and range, circuit diagram drawn with a pencil and ruler, procedure, observation table, sample calculation, graph and result; note meter types (MC or MI) and least count.\nCheck the circuit with the teacher before switching on; keep rheostats at the safe position (maximum resistance in armature, minimum in the field of a shunt motor) at start.\nIn viva, be ready to say why a particular meter or connection is used, what the graph shape means, and the safety precaution for every machine.",
 exps:[
 labX("Verification of KCL and KVL","Verify that the algebraic sum of currents at a node is zero and of voltages around a loop is zero.","DC supply, resistors, ammeters, voltmeters, breadboard, connecting wires",
  "KCL: ΣI = 0 at a node. KVL: ΣV = 0 around a closed loop.",
  [["State KCL.","The algebraic sum of currents meeting at a node is zero; charge is conserved."],["State KVL.","The algebraic sum of voltage drops and sources around any closed loop is zero."],["Do these laws hold for AC?","Yes, when instantaneous values or phasors are used."]]),
 labX("Verification of Thevenin's and Norton's theorems","Replace a linear network with its Thevenin and Norton equivalents and verify the load current.","DC sources, resistors, ammeter, voltmeter, rheostat, breadboard",
  "I_L = V_th/(R_th + R_L); I_N = V_th/R_th; R_th = R_N.",
  [["How is R_th found?","Deactivate the independent sources (short voltage, open current) and find the resistance across the load terminals."],["How are the Thevenin and Norton equivalents related?","V_th = I_N R_th, and both have the same equivalent resistance."],["To what networks do they apply?","Linear, bilateral networks."]]),
 labX("Verification of maximum power transfer and superposition theorems","Show that maximum power passes to the load when R_L = R_th, and that responses from independent sources add up.","DC supply, rheostat or decade box, ammeter, voltmeter, resistors",
  "P_max = V_th²/(4R_th) at R_L = R_th, efficiency 50 %. Superposition: I = I₁ + I₂ + ...",
  [["State the maximum power transfer theorem.","A source delivers maximum power to a load when the load resistance equals the source's internal (Thevenin) resistance."],["What is the efficiency at maximum power transfer?","50 %."],["Can superposition be applied to power?","No, because power depends on the square of current, which is nonlinear."]]),
 labX("Measurement of power in a three phase circuit by two wattmeter method","Measure the total power of a balanced three-phase load and find its power factor.","Three-phase supply, two wattmeters, three-phase load (lamp or inductive), voltmeter, ammeter",
  "P = W₁ + W₂; tanφ = √3(W₁ − W₂)/(W₁ + W₂); power factor = cosφ.",
  [["What happens to the readings at 0.5 power factor?","One wattmeter reads zero and the other reads the total power."],["When does one wattmeter read negative?","When the power factor is below 0.5 lagging (or leading); its terminals must be reversed."],["Does it work for unbalanced loads?","Yes, for a three-wire system with any load."]]),
 labX("Measurement of efficiency of a single phase transformer by load test","Load a transformer, measure input and output power at various loads and plot efficiency and regulation.","Single-phase transformer, autotransformer, wattmeters, ammeters, voltmeters, resistive load",
  "η = (output power/input power) × 100 = V₂I₂cosφ/W₁ × 100; regulation = (V_NL − V_FL)/V_NL × 100.",
  [["When is transformer efficiency maximum?","When the copper loss equals the iron loss."],["Which losses exist in a transformer?","Iron loss (hysteresis and eddy current) and copper loss in the windings."],["Why is efficiency high compared to rotating machines?","A transformer has no moving parts, so no mechanical losses."]]),
 labX("Determination of parameters and losses in a single phase transformer by OC and SC test","Find the equivalent circuit parameters, iron loss and full-load copper loss without loading the transformer.","Single-phase transformer, wattmeter, ammeter, voltmeter, variac",
  "OC test: W₀ = V₁I₀cosφ₀, R₀ = V₁/(I₀cosφ₀), X₀ = V₁/(I₀sinφ₀). SC test: R₀₁ = W_sc/I_sc², Z₀₁ = V_sc/I_sc, X₀₁ = √(Z₀₁² − R₀₁²).",
  [["What does the OC test give?","Core (iron) loss and the magnetising branch parameters."],["Why is the OC test done on the LV side and the SC test on the HV side?","The LV side lets rated voltage be applied conveniently; the HV side has a smaller rated current, so lower-range meters can be used."],["Why is SC wattmeter reading equal to copper loss?","The applied voltage is very small, so the flux and iron loss are negligible."]]),
 labX("Load characteristics of a DC generator","Plot the terminal voltage against load current for a DC generator.","DC generator coupled to a prime mover, field rheostat, ammeter, voltmeter, load bank, tachometer",
  "E = V + I_aR_a; E = PφZN/(60A).",
  [["Why does the terminal voltage of a shunt generator fall with load?","Due to armature resistance drop, armature reaction, and reduced field current."],["What is critical resistance?","The maximum field circuit resistance for which the shunt generator will still build up voltage."],["What are the conditions for voltage build-up?","Residual magnetism, the field connections in the correct polarity and field resistance below the critical value."]]),
 labX("Speed control of DC shunt motor","Vary motor speed by field-flux and armature-voltage control and plot speed against field current or armature voltage.","DC shunt motor, field rheostat, armature rheostat, ammeter, voltmeter, tachometer, 3-point starter",
  "N ∝ E_b/φ = (V − I_aR_a)/φ. Flux control gives speed above rated; armature control gives speed below rated.",
  [["What happens to speed if field current is reduced?","Flux falls, so speed rises."],["Why is a starter required?","At start E_b = 0, so the armature current would be very high without external resistance."],["Why must the field circuit of a shunt motor never be opened?","Flux drops to residual value and the motor speed can rise dangerously."]]),
 labX("Study of running and reversing of a three phase induction motor","Start a three-phase induction motor, observe its running condition and reverse the direction of rotation.","Three-phase induction motor, DOL or star-delta starter, three-phase supply, tachometer, ammeter, voltmeter",
  "N_s = 120f/P; slip s = (N_s − N)/N_s. Direction reverses on interchanging any two supply lines.",
  [["How is the direction of rotation reversed?","Interchange any two of the three supply lines to reverse the phase sequence."],["What is slip?","The relative speed between the rotating field and the rotor, as a fraction of synchronous speed."],["Why is a starter used?","Starting current is 5 to 7 times full load, and the starter limits it."]]),
 labX("Calibration of a single phase energy meter","Compare the energy shown by a meter with the true energy and find its percentage error.","Single-phase energy meter, wattmeter, lamp load, stop-watch, voltmeter, ammeter",
  "True energy = P × t; % error = (recorded − true)/true × 100. Meter constant = revolutions per kWh.",
  [["Which principle does an induction-type energy meter use?","The induction principle; the eddy currents produced in the aluminium disc give a driving torque."],["What is the meter constant?","Number of disc revolutions per kWh."],["What retards the disc from speeding up indefinitely?","The braking magnet produces an eddy-current braking torque proportional to speed."]])
 ]
});

sylAdd("ECP-001",{
 n:"Basic Electronics Engineering Lab", s:"BEEn Lab", type:"lab", ltp:"0-0-2", cr:1, sem:"I or II (group-wise)",
 marks:{sess:25,ext:25,total:50},
 obj:["To introduce hands-on descriptions of various physical and analytical concepts of electronic devices such as diodes, transistors, operational amplifiers and logic gates and their applications."],
 out:["Understand characteristics of various circuits using diode.","Analyze characteristics of various circuits using BJT.","Analyze characteristics of various circuits using FET.","Implement various logic gates and verify their truth-tables.","Improve skills of team work, technical communication and report writing."],
 rule:"All experiments (manuals and handouts available in the lab)",
 note:"Record format: aim, components with type numbers (e.g. IN4007, BC547, 7400), circuit diagram, observation tables, graph paper plots and result; mark the pin diagram of every device.\nCheck the polarity, supply level and ground before power-on; test diodes and transistors with a multimeter first, and keep the function generator amplitude low.\nExaminers ask for the working point, the region of operation and what each graph tells you; learn one line for each curve on your graph.",
 exps:[
 labX("To determine and plot V-I characteristics of P-N junction in both forward bias and reverse bias","Plot the diode characteristics, and find the knee voltage, dynamic resistance and reverse saturation current.","PN diode (IN4007), DC supply, resistor, voltmeter, milliammeter, microammeter, breadboard",
  "I = I₀(e^{V/ηV_T} − 1), V_T = kT/q ≈ 26 mV at 300 K; dynamic resistance r_d = ΔV/ΔI.",
  [["What is the cut-in voltage of Si and Ge diodes?","About 0.7 V for silicon and 0.3 V for germanium."],["Why is reverse current very small?","Only minority carriers flow; the depletion region blocks majority carriers."],["What is dynamic resistance?","The ratio of small change in voltage to change in current, r_d = ΔV/ΔI, at a given operating point."]]),
 labX("To determine and plot the wave shapes of clipping and clamping circuits","Observe how diode circuits clip a waveform at a level or shift its DC level.","Signal generator, CRO, diodes, resistors, capacitor, DC bias source",
  "Clipper limits the output to the diode threshold plus the bias; a clamper shifts the waveform by about the peak value without changing its shape.",
  [["What is the difference between a clipper and a clamper?","A clipper removes part of the waveform; a clamper adds a DC level but keeps the shape and peak-to-peak value."],["Why is the RC time constant of a clamper large?","So that the capacitor holds its charge during the cycle, keeping the DC shift steady."],["What does a series positive clipper do?","It removes the positive half cycle (or the part above the reference level)."]]),
 labX("To determine the ripple in the output of a half wave and a full wave rectifier at different loads","Measure the DC and AC output, and calculate the ripple factor with and without a filter.","Transformer, diodes, load resistors, capacitor, CRO, multimeter",
  "γ = V_rms(ac)/V_dc; half wave 1.21, full wave 0.482; V_dc = V_m/π (HW), 2V_m/π (FW).",
  [["What is the ripple factor?","The ratio of the RMS value of AC component to the DC value in the output."],["What is the ripple frequency of a full wave rectifier?","Twice the input frequency (100 Hz for a 50 Hz supply)."],["What are the maximum efficiencies of HW and FW rectifiers?","40.6 % for half wave and 81.2 % for full wave."]]),
 labX("To determine and plot V-I characteristics of Zener diode in both forward bias and reverse bias","Plot Zener characteristics and find the breakdown voltage and dynamic resistance in the breakdown region.","Zener diode, DC supply, series resistor, voltmeter, milliammeter",
  "Regulator: R_s = (V_in − V_Z)/(I_Z + I_L); Zener dynamic resistance r_z = ΔV_Z/ΔI_Z.",
  [["In which bias is a Zener diode used as a regulator?","Reverse bias, in the breakdown region, where voltage stays nearly constant."],["What are the two breakdown mechanisms?","Zener breakdown (below about 5 V) and avalanche breakdown (above about 5 V)."],["Why is a series resistor needed?","It limits the current below the maximum power rating of the diode."]]),
 labX("To determine and plot input and output characteristics of NPN and PNP bipolar junction transistors in common emitter and common base mode","Plot the input and output characteristics and find h-parameters, α and β.","BJT (BC547 or BC557), DC supplies, resistors, voltmeters, ammeters",
  "β = I_C/I_B, α = I_C/I_E, β = α/(1 − α); input resistance = ΔV_BE/ΔI_B; output resistance = ΔV_CE/ΔI_C.",
  [["How is the transistor biased in the active region?","The emitter-base junction is forward biased and the collector-base junction is reverse biased."],["Which configuration has the highest power gain?","Common emitter, with a large current gain β and a large voltage gain (common collector has a similar current gain 1 + β but no voltage gain)."],["Why is the base made thin and lightly doped?","So that most of the injected carriers reach the collector without recombining in the base."]]),
 labX("To determine and plot input and output characteristics of a field-effect transistor","Plot drain and transfer characteristics of a JFET and find pinch-off voltage, I_DSS and g_m.","JFET (BFW10), DC supplies, voltmeters, milliammeter, resistors",
  "I_D = I_DSS(1 − V_GS/V_P)²; g_m = ΔI_D/ΔV_GS; r_d = ΔV_DS/ΔI_D; μ = g_m r_d.",
  [["What is pinch-off voltage?","The gate-source voltage V_P at which the channel closes and I_D falls to zero; with V_GS = 0 the drain current saturates once V_DS reaches |V_P|."],["Why does a JFET have high input impedance?","The gate-channel junction is reverse-biased, so gate current is very small."],["Is a JFET bipolar or unipolar?","Unipolar; only one type of carrier carries current."]]),
 labX("To determine and plot input and output characteristics of a metal-oxide-semiconductor field-effect transistor","Plot drain and transfer characteristics of a MOSFET and find the threshold voltage and transconductance.","MOSFET (n-channel enhancement), DC supplies, voltmeters, ammeter, resistors",
  "Saturation: I_D = k(V_GS − V_T)²; g_m = ΔI_D/ΔV_GS.",
  [["What is the threshold voltage?","The minimum gate-source voltage that forms a conducting channel in an enhancement MOSFET."],["Why is the gate current nearly zero?","The oxide layer insulates the gate from the channel."],["How do enhancement and depletion MOSFETs differ?","An enhancement device conducts only after the gate voltage induces a channel; a depletion device has a built-in channel."]]),
 labX("To determine and plot the frequency response of an amplifier","Measure gain over a range of frequencies and find the half-power points and bandwidth.","CE amplifier, function generator, CRO, DC supply, resistors and capacitors",
  "Gain (dB) = 20 log₁₀(V_o/V_i); bandwidth BW = f_H − f_L, at the −3 dB (0.707 × mid-band gain) points.",
  [["What is bandwidth?","The frequency range between the lower and upper 3 dB (half-power) frequencies."],["Why does gain fall at low frequencies?","The coupling and bypass capacitors present higher reactance."],["Why does gain fall at high frequencies?","Transistor junction capacitances and stray capacitances shunt the signal."]]),
 labX("Realization and verification of the truth table of various logic gates","Verify the truth tables of AND, OR, NOT, NAND, NOR, XOR and XNOR gates using ICs.","Gate ICs (7408, 7432, 7404, 7400, 7402, 7486), logic trainer kit, LEDs, +5 V supply",
  "Y = A·B (AND), A + B (OR), A′ (NOT), (A·B)′ (NAND), (A + B)′ (NOR), A ⊕ B (XOR).",
  [["Which gates are universal?","NAND and NOR, since any Boolean function can be built from either."],["What is the output of an XOR gate?","High when the inputs differ, low when they are the same."],["What voltage level does TTL use for logic 1?","About 2 V to 5 V; logic 0 is 0 to 0.8 V."]]),
 labX("Realization and verification of the basic logic gates using NAND and NOR gates","Build NOT, AND and OR gates using only NAND or only NOR gates and verify their truth tables.","NAND IC 7400, NOR IC 7402, logic trainer kit, LEDs, +5 V supply",
  "NAND: NOT = (A·A)′, AND = ((A·B)′)′, OR = (A′·B′)′. De Morgan: (A + B)′ = A′·B′.",
  [["How do you make a NOT gate from a NAND gate?","Tie both inputs together; then Y = (A·A)′ = A′."],["State De Morgan's theorems.","(A + B)′ = A′B′ and (AB)′ = A′ + B′."],["Why are NAND gates called universal?","Every logic function can be made from NAND gates alone."]]),
 labX("To design inverting and non-inverting amplifier using op-amp","Build both op-amp amplifiers and verify their gains for different resistor ratios.","IC 741 op-amp, ±12 V supply, resistors, function generator, CRO",
  "Inverting: A_v = −R_f/R₁. Non-inverting: A_v = 1 + R_f/R₁.",
  [["What is a virtual ground?","In an inverting amplifier, the inverting input is at almost 0 V because of the very high open-loop gain."],["What are the ideal op-amp properties?","Infinite gain, infinite input impedance, zero output impedance and infinite bandwidth."],["Why is negative feedback used?","It stabilises the gain, widens the bandwidth and reduces distortion."]])
 ]
});

sylAdd("MEP-001",{
 n:"Basic Mechanical Engineering Lab", s:"BME Lab", type:"lab", ltp:"0-0-2", cr:1, sem:"I or II (group-wise)",
 marks:{sess:25,ext:25,total:50},
 obj:["To help students visualize various concepts and perform experiments on different apparatus to gain practical knowledge in basic mechanical engineering."],
 out:["Understand and explain the functioning of SI and CI engines.","Understand the internal operation occurring in the working of fluid machines.","Perform the impact test (Izod/Charpy) on the impact testing machine.","Understand concepts like moment of inertia and coefficient of friction by performing on the apparatus.","Perform and study various measurement instruments."],
 rule:"A minimum of 10 experiments from the following",
 note:"Record format: aim, apparatus and specifications, neat labelled sketch, theory with formulas, observation table with units, sample calculation, graph if required, result and precautions.\nFor testing machines (UTM, impact) record the specimen dimensions before the test and the load or energy readings; draw the load-extension curve with the yield, ultimate and fracture points marked.\nIn viva, be ready to name the parts of the model or machine, state the working principle in two lines and say the sources of error.",
 exps:[
 labX("Study of 2-stroke and 4-stroke I.C. engine models","Understand the parts and working cycle of two-stroke and four-stroke engines.","Cut-section models of 2-stroke and 4-stroke petrol engines",
  "4-stroke: one power stroke every 2 revolutions (720°); 2-stroke: one every revolution. Otto efficiency η = 1 − 1/r^{γ−1}.",
  [["Name the four strokes of a four-stroke engine.","Suction (intake), compression, power (expansion) and exhaust."],["How many crankshaft revolutions per cycle in a 2-stroke and a 4-stroke engine?","One for a two-stroke and two for a four-stroke."],["What are the ports in a 2-stroke engine used for?","Inlet, transfer and exhaust ports replace valves and control the gas flow."]]),
 labX("Study of Fiat engine and/or diesel engine prototype","Study the construction, parts and working of a petrol (Fiat) or diesel engine prototype.","Fiat engine or diesel engine prototype, models of piston, valve, crankshaft, fuel injector",
  "Compression ratio r = (V_s + V_c)/V_c; SI engine r ≈ 6-10, CI engine r ≈ 14-22.",
  [["How does a CI engine ignite the fuel?","Compression heats the air above the fuel's ignition temperature, so injected fuel ignites by itself."],["Why does a diesel engine have a higher compression ratio?","Compression alone must ignite the fuel, so it needs higher air temperature."],["Name the main parts of an engine.","Cylinder, piston, connecting rod, crankshaft, valves, camshaft and flywheel."]]),
 labX("To conduct the tensile test on a UTM and determine ultimate tensile strength and percentage elongation for a steel specimen","Pull a steel specimen to failure and obtain its stress-strain behaviour and key strength values.","Universal testing machine, steel specimen, vernier caliper, extensometer, marking punch",
  "UTS = P_max/A₀; % elongation = (L_f − L₀)/L₀ × 100; % reduction in area = (A₀ − A_f)/A₀ × 100; E = σ/ε in the elastic range.",
  [["What is the yield point?","The stress at which the material begins to deform plastically without a load increase."],["What is ductility and how is it measured?","Ability to deform plastically before fracture; measured by percentage elongation and reduction in area."],["Why is gauge length marked on the specimen?","Elongation is measured over a fixed gauge length, so the results are comparable."]]),
 labX("To conduct the compression test and determine the ultimate compressive strength for a specimen","Load a specimen in compression until failure and calculate its compressive strength.","UTM or compression testing machine, cast iron or concrete specimen, vernier caliper",
  "σ_c = P_max/A₀; brittle materials such as cast iron fail by shear near 45°.",
  [["Which materials are strong in compression?","Brittle materials such as cast iron and concrete are much stronger in compression than in tension."],["How does cast iron fail in compression?","By shear along a plane inclined at roughly 45° to the axis."],["Why is a specimen with a small L/D ratio used?","To avoid buckling, so that failure is by crushing."]]),
 labX("To conduct the impact test (Izod/Charpy) on the impact testing machine and to find the impact strength","Find the energy absorbed by a notched specimen when struck by a swinging pendulum.","Impact testing machine (Izod or Charpy), notched specimens, vernier caliper",
  "Energy absorbed = mg R(cosβ − cosα) (J); impact strength = energy/cross-section area at the notch.",
  [["Difference between Izod and Charpy tests?","Charpy uses a simply supported beam struck at the middle; Izod uses a cantilever struck at the free end."],["Why is the specimen notched?","The notch concentrates stress and triggers the fracture under worst-case conditions."],["What does high impact strength show?","High toughness, meaning the material absorbs a lot of energy before fracture."]]),
 labX("To determine the value of acceleration due to gravity by Atwood's machine apparatus","Measure the acceleration of two unequal masses over a pulley and calculate g.","Atwood machine, pulley, thread, two masses, stop-watch, scale",
  "a = (m₁ − m₂)g/(m₁ + m₂); a = 2s/t², so g = 2s(m₁ + m₂)/[t²(m₁ − m₂)]. Tension T = 2m₁m₂g/(m₁ + m₂).",
  [["Why is the difference in masses small?","A small difference gives a small acceleration that can be timed accurately."],["What is neglected in the formula?","Mass of the string, pulley inertia and friction."],["What is the tension in the string?","T = 2m₁m₂g/(m₁ + m₂)."]]),
 labX("To verify the principle of moments by bell crank lever apparatus","Verify that the sum of clockwise and anticlockwise moments about the fulcrum is equal at equilibrium.","Bell crank lever apparatus, weights, hanger, scale",
  "W·a = P·b (moments about the fulcrum); clockwise moments = anticlockwise moments.",
  [["State the principle of moments.","For a body in equilibrium the sum of clockwise moments about any point equals the sum of anticlockwise moments."],["What is a bell crank lever used for?","To change the direction of a force by 90° and amplify it."],["Where is the fulcrum located?","At the junction of the two arms, which are set at right angles."]]),
 labX("To determine the moment of inertia of a flywheel apparatus about its axis of rotation","Find the moment of inertia of a flywheel by letting a falling mass rotate it.","Flywheel with axle, hanging mass, string, stop-watch, vernier caliper, scale",
  "I = m r²(g t²/(2h) − 1), neglecting friction; r = axle radius, h = fall height, t = time of fall.",
  [["What is moment of inertia?","The rotational analogue of mass: I = Σmr², resistance to change in angular motion."],["Why does a flywheel have most of its mass at the rim?","A large I at the rim smooths out speed fluctuations."],["What is the SI unit of I?","kg·m²."]]),
 labX("To verify Newton's second law of motion by Fletcher's trolley apparatus","Show that acceleration is proportional to force when mass is constant, and inversely proportional to mass at constant force.","Fletcher's trolley, inclined or horizontal track, weights, pulley, stop-watch, scale",
  "F = ma; a = 2s/t². Plot a against F, a straight line through the origin.",
  [["State Newton's second law.","The rate of change of momentum is proportional to the applied force, so F = ma for constant mass."],["Why is friction compensated on the track?","Otherwise the measured net force would be less than the applied force."],["What does the a-F graph show?","A straight line whose slope is 1/m."]]),
 labX("To find the coefficient of friction by combined inclined plane and friction slide apparatus","Determine the coefficient of friction between two surfaces using an inclined plane and a slide.","Inclined plane with friction slide, blocks, weights, protractor, pulley",
  "μ = tanφ (angle of friction, equal to angle of repose); on horizontal slide μ = F/N.",
  [["Define the coefficient of friction.","The ratio of limiting friction to the normal reaction, μ = F/N."],["What is the angle of repose?","The maximum slope at which a body stays at rest without sliding; tanφ = μ."],["Is static or kinetic friction greater?","Static (limiting) friction is greater than kinetic friction."]]),
 labX("To verify Bernoulli's equation","Verify the conservation of energy of a flowing fluid using a Venturimeter or a tapered pipe.","Bernoulli's apparatus, Venturi tube with piezometers, water supply, measuring tank, stop-watch",
  "p/ρg + v²/2g + z = constant (total head); v = Q/A.",
  [["State Bernoulli's theorem.","For steady, incompressible, non-viscous flow, the total energy per unit weight along a streamline stays constant."],["What is the significance of pressure head, velocity head and datum head?","They are the energy per unit weight due to pressure, motion and elevation."],["Why do the measured heads differ slightly from ideal?","Viscous losses cause a small drop in total head."]]),
 labX("Study and working of hydraulic turbines and pumps","Understand the construction and working of Pelton, Francis, Kaplan turbines and centrifugal and reciprocating pumps.","Models of Pelton wheel, Francis turbine, Kaplan turbine, centrifugal pump, reciprocating pump",
  "Pelton: impulse, high head. Francis: reaction, medium head. Kaplan: axial flow, low head. Specific speed N_s = N√P/H^{5/4}.",
  [["Which turbine suits high head and low discharge?","Pelton wheel, an impulse turbine."],["What is priming of a centrifugal pump?","Filling the casing and suction pipe with liquid before start so that air does not stop pumping."],["What is the difference between impulse and reaction turbines?","In impulse, the water pressure is atmospheric at the runner; in reaction, pressure drops across the runner."]]),
 labX("Study and working of different types of measuring instruments like vernier caliper, micrometer, height gauge, sine bar, dial gauge etc.","Learn the principle, least count and use of common linear and angular measuring instruments.","Vernier caliper, outside micrometer, height gauge, sine bar with slip gauges, dial gauge, surface plate",
  "Vernier least count = 1 MSD − 1 VSD (e.g. 0.02 mm); micrometer LC = pitch/divisions = 0.5/50 = 0.01 mm; sine bar: sinθ = h/L.",
  [["What is least count?","The smallest length an instrument can measure accurately."],["What is zero error?","A non-zero reading when the jaws are closed; it is subtracted from the readings."],["How does a sine bar measure angles?","With slip gauges of height h under one roller, sinθ = h/L, L being the roller spacing."]]),
 labX("Identification of twenty five common materials and their application","Recognise common engineering materials and state their properties and uses.","Sample set of metals, alloys, polymers, ceramics and composites",
  "Classes: ferrous (mild steel, cast iron), non-ferrous (Al, Cu, brass = Cu + Zn, bronze = Cu + Sn), polymers, ceramics and composites.",
  [["What is the difference between brass and bronze?","Brass is a copper-zinc alloy; bronze is a copper-tin alloy."],["What is the carbon content of mild steel and cast iron?","Mild steel has about 0.15-0.3 % C; cast iron has about 2-4 % C."],["Why is aluminium used in aircraft?","Its high strength-to-weight ratio and corrosion resistance."]])
 ]
});
